        'The military has declassified restricted combat maneuvers for all Hunters. All enemies defeated this weekend will grant **3x Experience Points**!' => '軍部は全ハンターの制限戦闘機動を解除した。今週末に倒した全ての敵から **経験値3倍** を獲得！',
        'The most elite Hunters on Pioneer 2. These legends have proven their worth by completing the most bounties.' => 'パイオニア2屈指のエリートハンター。最も多くのバウンティを達成した伝説のプレイヤーたちです。',
        'The official Pioneer 2 Bounty Board. Complete unique, specially curated quests to earn meseta, rare items, and global recognition.' => 'パイオニア2公式バウンティボード。厳選されたユニークなクエストをクリアして、メセタやレアアイテム、栄誉を獲得しましょう。',
        'The top 3 event contributors receive a grand 100,000 Meseta prize and a prestigious choice of bonus rare items!' => 'The top 3 event contributors receive a grand 100,000 Meseta prize and a prestigious choice of bonus rare items!',
        'This confirmation link has expired. Confirmation links are valid for 24 hours. Please log in and request a new confirmation link.' => 'この確認リンクは有効期限が切れています（有効期限は24時間です）。ログインして新しい確認リンクをリクエストしてください。',
        'This confirmation link is invalid or has already been used. Please log in to check your account settings.' => 'この確認リンクは無効か、既に使用されています。ログインしてアカウント設定をご確認ください。',
        'This email address has already been claimed by another account.' => 'このメールアドレスは既に別のアカウントに登録されています。',
        'This email will be used exclusively for password recovery via the Forgot Password page if you ever lose or forget your account password.' => 'このメールアドレスは、パスワードを紛失または忘れた際にパスワード再設定ページから再設定を行うために使用されます。',
        'This recovery email address has already been confirmed and is active on your account.' => 'このリカバリー用メールアドレスは既に確認されており、アカウントで有効です。',
