        'Select and immediately activate one of the curated, high-volume month-long **Boss Rush** server-wide events:' => '厳選された1ヶ月間の大規模ボスラッシュサーバーイベントを選択して即座に開始します：',
        'Month' => '月',
        'Target:' => '目標:',
        'Corrupted cybernetic mainframes are spawning simulations across Ragol! Cooperate server-wide to defeat Vol Opt in Ep1 (+1 pt), Gol Dragon in Ep2 (+2 pts), or Shambertin in Ep4 (+3 pts). Earn difficulty bonuses (+1 Hard, +2 VHard, +3 Ult)! Earn 3 random rare drops tailored to your character level!' => '暴走したサイバネティックメインフレームがラグオル全域にシミュレーションを展開中！サーバー全員で協力し、Ep1のVol Opt（+1pt）、Ep2のGol Dragon（+2pts）、またはEp4のShambertin（+3pts）を討伐せよ。難易度ボーナス（Hard+1、VHard+2、Ult+3）あり！キャラクターレベルに応じたランダムレアアイテム3種を獲得可能！',
        'Operation: Ancient Cataclysm' => 'オペレーション：エンシェント・カタクリズム',
        'An ancient seal has broken, triggering a massive assault from the wildlife! Defeat any Episode 1 boss: Dragon (+1 pt), De Rol Le (+2 pts), Vol Opt (+3 pts), or Dark Falz (+4 pts). Earn difficulty bonuses (+1 Hard, +2 VHard, +3 Ult)!' => '古代の封印が破られ、原生生物による大規模襲撃が始まった！エピソード1の任意のボスを討伐せよ：Dragon（+1pt）、De Rol Le（+2pts）、Vol Opt（+3pts）、Dark Falz（+4pts）。難易度ボーナス（Hard+1、VHard+2、Ult+3）あり！',
        'Operation: Seabed Infestation' => 'オペレーション：シーベッド・インフェステーション',
        'The Sub-Seabed laboratories are overflowing with mutated threats! Defeat any Episode 2 boss: Barba Ray (+1 pt), Gol Dragon (+2 pts), Gal Gryphon (+3 pts), or Olga Flow (+4 pts). Earn difficulty bonuses (+1 Hard, +2 VHard, +3 Ult)!' => '海底研究所が変異体の脅威で溢れかえっている！エピソード2の任意のボスを討伐せよ：Barba Ray（+1pt）、Gol Dragon（+2pts）、Gal Gryphon（+3pts）、Olga Flow（+4pts）。難易度ボーナス（Hard+1、VHard+2、Ult+3）あり！',
        'Operation: Draconic Dominion' => 'オペレーション：ドラコニック・ドミニオン',
        'Ancient and simulated dragons have established a scorching grip across all episodes! Defeat Dragon in Ep1 (+1 pt), Gol Dragon in Ep2 (+2 pts), or Shambertin in Ep4 (+3 pts). Earn difficulty bonuses (+1 Hard, +2 VHard, +3 Ult)!' => '古代種およびシミュレーションのドラゴンが全エピソードを猛火で掌握した！Ep1のDragon（+1pt）、Ep2のGol Dragon（+2pts）、Ep4のShambertin（+3pts）を討伐せよ。難易度ボーナス（Hard+1、VHard+2、Ult+3）あり！',
        'Operation: The Ultimate Gauntlet' => 'オペレーション：アルティメット・ガントレット',
        'The Hunters Guild has issued an absolute extermination order. Defeat ANY boss in the entire game! Points are scaled by boss tier (Dragon/Barba Ray +1, De Rol Le/Gol Dragon +2, Vol Opt/Gal Gryphon +3, Dark Falz/Olga Flow/Shambertin +4) plus difficulty bonuses (+1 Hard, +2 VHard, +3 Ult)!' => 'ハンターズギルドより完全殲滅指令が発令された。全エピソードのすべてのボスを討伐せよ！獲得ポイントはボスのティア（Dragon/Barba Ray +1、De Rol Le/Gol Dragon +2、Vol Opt/Gal Gryphon +3、Dark Falz/Olga Flow/Shambertin +4）および難易度ボーナス（Hard+1、VHard+2、Ult+3）に応じて加算！',
        'Operation: Cataclysmic Core' => 'オペレーション：カタクリズミック・コア',
        'The core dimensional anomalies threaten to destabilize Ragol! Cooperate to defeat the final boss of each episode: Dark Falz in Ep1 (+3 pts), Olga Flow in Ep2 (+4 pts), or Shambertin in Ep4 (+4 pts). Earn difficulty bonuses (+1 Hard, +2 VHard, +3 Ult)!' => '中核の次元異常がラグオル崩壊の危機を引き起こしている！協力して各エピソードの最終ボスを撃破せよ：Ep1のDark Falz（+3pts）、Ep2のOlga Flow（+4pts）、Ep4のShambertin（+4pts）。難易度ボーナス（Hard+1、VHard+2、Ult+3）あり！',
        'Currently Tracked Player Missions (Last 50)' => '現在追跡中のプレイヤーミッション（最新50件）',
