        'Linux & Steam Deck' => 'Linux и Steam Deck',
        'LiquidSpikes is one of the builders of the psobb.io server infrastructure. He helps manage the backend clusters, keeps the database ticking, and maintains the web dashboard. He is incredibly grateful to the amazing community of hunters who call psobb.io home—thank you so much for playing, exploring, and keeping this timeless Sega classic alive!' => 'LiquidSpikes — один из создателей инфраструктуры psobb.io. Он управляет серверными кластерами, поддерживает базу данных и развивает веб-портал. Он безмерно благодарен замечательному сообществу охотников psobb.io: спасибо вам за игру, исследования и сохранение этой бессмертной классики Sega!',
        'List character slots on your account, indicating which are used or free.' => 'Показать список слотов персонажей на аккаунте.',
