        'Log into the Player Dashboard daily to accumulate bonus rewards, rare materials, and consumable items to enhance your Ragol exploration.' => 'Заходите в Панель игрока каждый день, чтобы накапливать бонусные награды, редкие материалы и расходные предметы для исследования Рагола.',
