        'Pixelated is our resident vibe-coding beast, dropping awesome client-side mods like custom HD texture packs and camera controls inside our Discord, alongside plenty of legendary memes. Pixelated keeps our community connected, entertained, and equipped with cool gaming utilities.' => 'Pixelated — наш мастер атмосферного кода, создающий классные клиентские моды (HD-текстуры, управление камерой) и отличные мемы в Discord. Он помогает нашему сообществу оставаться дружным и обеспеченным крутыми утилитами.',
        'Pixelated is our resident vibe-coding beast, dropping awesome client-side mods like custom HD texture packs and camera controls inside our Discord, alongside plenty of legendary memes. Pixelated keeps our community connected, entertained, and equipped with cool gaming utilities. As Pixelated famously said: "I am Optimizer Prime, wrangler of clankers".' => 'Pixelated — наш мастер атмосферного кода, создающий великолепные клиентские моды (вроде HD-текстур и управления камерой), а также снабжающий Discord отличными мемами. Он объединяет сообщество и радует охотников крутыми утилитами.',
