        'Swap inventory bank on the fly! $bank 0 for Shared Bank, $bank 1-127 for Character Banks.' => 'Быстрое переключение банка на лету! $bank 0 для общего банка, $bank 1-127 для персональных банков.',
        'Swap your inventory bank container on the fly using the pre-selector dropdown. Switch to the Shared Bank or any character bank (Character 1-20).' => 'Переключайте банк инвентаря на лету с помощью выпадающего меню. Переключайтесь между Общим банком и любым персональным банком (Персонажи 1-20).',
