        'TIME PLAYED' => 'ВРЕМЯ В ИГРЕ',
        'Take on unique, personalized bounties offering exclusive gear and material rewards. Track your boss kills and exploration objectives directly on the web, and claim your loot instantly to your character in-game.' => 'Выполняйте уникальные персональные заказы с наградами в виде редкой экипировки и материалов. Отслеживайте убийства боссов и цели исследований прямо на сайте и мгновенно получайте награду в игре.',
        'Tally all consumed Stat Materials (Power, Mind, HP, TP, Evade, Def, Luck) and progress toward caps.' => 'Подсчитать все использованные материалы (Power, Mind, HP, TP, Evade, Def, Luck) и прогресс до максимальных значений.',
