        'Textures' => 'Текстуры',
        'The Game Master automatically generates specially curated bounties tailored specifically to your character\'s stats and classes.' => 'Гейм-мастер автоматически генерирует специальные контракты, адаптированные под характеристики и класс вашего персонажа.',
        'The LFG Terminal synchronizes with the server in real-time, displaying your current online status, active character class, level, and active game lobby ID.' => 'Терминал LFG синхронизируется с сервером в реальном времени, отображая статус онлайн, класс активного персонажа, уровень и номер лобби.',
        'The Launcher will extract your mod <strong>directly</strong> into the game\'s root directory. Your .zip file must maintain the correct folder structure and should NOT contain an extra top-level folder.' => 'Лаунчер распакует ваш мод <strong>напрямую</strong> в корневую папку игры. Ваш .zip файл должен сохранять правильную структуру папок и НЕ должен содержать лишнюю корневую папку.',
        'The Top 3 leaderboard champions receive a grand 100,000 Meseta cash prize!' => 'Топ-3 лидеров получают главный денежный приз в 100,000 Месеты!',
        'The leaderboard is waiting for its first legend.' => 'Таблица лидеров ждет своего первого героя.',
        'The military has declassified restricted combat maneuvers for all Hunters. All enemies defeated this weekend will grant **3x Experience Points**!' => 'Военное ведомство разрешило применение особых боевых маневров для всех Охотников. За всех врагов, побежденных в эти выходные, начисляется **в 3 раза больше опыта**!',
        'The most elite Hunters on Pioneer 2. These legends have proven their worth by completing the most bounties.' => 'Элита Охотников Пионера-2. Эти легенды доказали свое превосходство, выполнив больше всех заказов.',
        'The official Pioneer 2 Bounty Board. Complete unique, specially curated quests to earn meseta, rare items, and global recognition.' => 'Официальная Доска заказов Пионера-2. Выполняйте уникальные квесты, чтобы зарабатывать месету, редкие предметы и всеобщее признание.',
        'The top 3 event contributors receive a grand 100,000 Meseta prize and a prestigious choice of bonus rare items!' => 'Тройка лидеров события получает главный приз в 100,000 Месеты и престижный выбор бонусных предметов!',
        'This confirmation link has expired. Confirmation links are valid for 24 hours. Please log in and request a new confirmation link.' => 'Срок действия этой ссылки подтверждения истек (ссылки действительны в течение 24 часов). Пожалуйста, войдите в аккаунт и запросите новую ссылку.',
        'This confirmation link is invalid or has already been used. Please log in to check your account settings.' => 'Эта ссылка подтверждения недействительна или уже была использована. Пожалуйста, войдите в систему и проверьте настройки учетной записи.',
        'This email address has already been claimed by another account.' => 'Этот адрес электронной почты уже используется другим аккаунтом.',
        'This email will be used exclusively for password recovery via the Forgot Password page if you ever lose or forget your account password.' => 'Этот email будет использоваться исключительно для восстановления пароля через страницу «Забыли пароль», если вы когда-либо потеряете доступ к аккаунту.',
        'This recovery email address has already been confirmed and is active on your account.' => 'Этот email для восстановления уже был подтвержден и активен на вашей учетной записи.',
        'This tab is currently unavailable because your account is not linked to Discord. Link your account to view and claim Tekker Challenge reward tokens.' => 'Эта вкладка недоступна, так как ваш аккаунт не привязан к Discord. Привяжите аккаунт, чтобы просматривать и забирать жетоны наград Теккера.',
        'Timestamp' => 'Время',
        'Toggle class tags (HUmar, FOnewearl, RAcast, etc.) to view only items usable by your class.' => 'Переключайте теги классов (HUmar, FOnewearl, RAcast и др.), чтобы видеть только доступные вам предметы.',
        'Toggles global broadcast announcements when you find rare items.' => 'Переключить глобальные серверные оповещения о найденных редких предметах.',
