        'View exact monster kill progress for equipped sealed rare weapons (e.g. Sealed J-Sword).' => 'Посмотреть прогресс убийств монстров для экипированного запечатанного оружия (напр. Sealed J-Sword).',
        'View your Guild\'s master roster, unspent team points, and next milestone unlocks from any device in real-time.' => 'Просматривайте состав гильдии, неиспользованные командные очки и следующие рубежи наград с любого устройства в реальном времени.',
        'View your Guild\'s master roster, unspent team points, and next milestone unlocks from any device.' => 'Просматривайте состав гильдии, неиспользованные очки команды и следующие рубежи наград с любого устройства.',
        'Viridia' => 'Viridia',
