        'WIPE ALL MATERIALS' => 'СБРОСИТЬ ВСЕ МАТЕРИАЛЫ',
        'Wall of Legends' => 'Стена Легенд',
        'Wall of Legends Leaderboard:' => 'Таблица лидеров Стены Легенд:',
        'Wand' => 'Палочка',
        'Warp Direct' => 'Телепорт Direct Warp',
        'Warp Direct Teleportation:' => 'Прямая телепортация Warp Direct:',
        'We are currently working on the final touches for the website and server. Please check back soon for more updates!' => 'В настоящее время мы вносим финальные штрихи в сайт и сервер. Загляните позже, чтобы узнать новости!',
        'We\'ve officially launched our Discord account linking! You can now securely tie your Discord profile directly to your in-game Hunter characters. Plus, interact with <strong>Mission Control</strong>—our new intelligent Discord chat companion! It recognizes your linked characters, monitors custom server status alerts, and assists with real-time guides right from the chat!' => 'Мы запустили привязку аккаунтов Discord! Теперь вы можете связать свой профиль Discord с игровыми охотниками. Кроме того, познакомьтесь с <strong>Mission Control</strong> — нашим новым ИИ-компаньоном в Discord! Он знает ваших персонажей, сообщает о статусе сервера и помогает советами прямо в чате!',
        'We\'ve updated our client to version <strong>1.25.13b</strong> (851MB). This new beta client supports both JP and EN players! Download it now from our <a href="downloads.php">downloads page</a>.' => 'Мы обновили клиент до версии <strong>1.25.13b</strong> (851 МБ). Новая версия поддерживает как японских, так и англоязычных игроков! Скачайте ее на нашей <a href="downloads.php">странице загрузок</a>.',
        'Weapon' => 'Оружие',
        'Weapon Choice 1' => 'Выбор оружия 1',
        'Weapon Choice 2' => 'Выбор оружия 2',
        'Weapon Choice 3' => 'Выбор оружия 3',
        'Weapon Package' => 'Набор оружия',
        'Weapons and armors are automatically curated based on your level and class. Armors come with 4 slots and high stats!' => 'Оружие и броня подбираются автоматически в зависимости от вашего уровня и класса. Броня выдается с 4 слотами и высокими параметрами!',
        'Web-to-Game Chat Console' => 'Веб-консоль чата в игре',
        'Welcome to the ultimate custom Phantasy Star Online Blue Burst server. Our mission is to seamlessly bridge classic 2004 Sega dreamscape nostalgia with bleeding-edge modern web capabilities, automated game services, and advanced AI integration.' => 'Добро пожаловать на лучший кастомный сервер Phantasy Star Online Blue Burst. Наша цель — соединить теплую ностальгию классики Sega 2004 года с передовыми возможностями современного веба, автоматическими игровыми сервисами и интеграцией искусственного интеллекта.',
        'Welcome,' => 'Добро пожаловать,',
        'While waiting for the download, <a href="/register.php">create account</a> via website login.' => 'Пока идет скачивание, <a href="/register.php">создайте аккаунт</a> на сайте.',
