        'Start Global Event!' => 'Запустить глобальное событие!',
        'Launch Curated Monthly Event' => 'Запуск официального ежемесячного события',
        'Select and immediately activate one of the curated, high-volume month-long **Boss Rush** server-wide events:' => 'Выберите и активируйте одно из официальных масштабных месячных событий Boss Rush:',
        'Month' => 'Месяц',
        'Target:' => 'Цель:',
        'Corrupted cybernetic mainframes are spawning simulations across Ragol! Cooperate server-wide to defeat Vol Opt in Ep1 (+1 pt), Gol Dragon in Ep2 (+2 pts), or Shambertin in Ep4 (+3 pts). Earn difficulty bonuses (+1 Hard, +2 VHard, +3 Ult)! Earn 3 random rare drops tailored to your character level!' => 'Зараженные мэйнфреймы генерируют боевые симуляции на Раголе! Объединитесь всем сервером, чтобы победить Vol Opt в Ep1 (+1 очко), Gol Dragon в Ep2 (+2 очка) или Shambertin в Ep4 (+3 очка). Бонусы за сложность (+1 Hard, +2 VHard, +3 Ult)! Награда — 3 случайных редких дропа под ваш уровень!',
        'Operation: Ancient Cataclysm' => 'Операция: Древний катаклизм',
        'An ancient seal has broken, triggering a massive assault from the wildlife! Defeat any Episode 1 boss: Dragon (+1 pt), De Rol Le (+2 pts), Vol Opt (+3 pts), or Dark Falz (+4 pts). Earn difficulty bonuses (+1 Hard, +2 VHard, +3 Ult)!' => 'Древняя печать разрушена, дикая фауна взбесилась! Победите любого босса Эпизода 1: Dragon (+1 очко), De Rol Le (+2 очка), Vol Opt (+3 очка) или Dark Falz (+4 очка). Бонусы за сложность (+1 Hard, +2 VHard, +3 Ult)!',
        'Operation: Seabed Infestation' => 'Операция: Заражение морского дна',
        'The Sub-Seabed laboratories are overflowing with mutated threats! Defeat any Episode 2 boss: Barba Ray (+1 pt), Gol Dragon (+2 pts), Gal Gryphon (+3 pts), or Olga Flow (+4 pts). Earn difficulty bonuses (+1 Hard, +2 VHard, +3 Ult)!' => 'Глубоководные лаборатории переполнены мутантами! Победите любого босса Эпизода 2: Barba Ray (+1 очко), Gol Dragon (+2 очка), Gal Gryphon (+3 очка) или Olga Flow (+4 очка). Бонусы за сложность (+1 Hard, +2 VHard, +3 Ult)!',
        'Operation: Draconic Dominion' => 'Операция: Владычество драконов',
        'Ancient and simulated dragons have established a scorching grip across all episodes! Defeat Dragon in Ep1 (+1 pt), Gol Dragon in Ep2 (+2 pts), or Shambertin in Ep4 (+3 pts). Earn difficulty bonuses (+1 Hard, +2 VHard, +3 Ult)!' => 'Древние и искусственные драконы захватили все эпизоды! Победите Dragon в Ep1 (+1 очко), Gol Dragon в Ep2 (+2 очка) или Shambertin в Ep4 (+3 очка). Бонусы за сложность (+1 Hard, +2 VHard, +3 Ult)!',
        'Operation: The Ultimate Gauntlet' => 'Операция: Абсолютное испытание',
        'The Hunters Guild has issued an absolute extermination order. Defeat ANY boss in the entire game! Points are scaled by boss tier (Dragon/Barba Ray +1, De Rol Le/Gol Dragon +2, Vol Opt/Gal Gryphon +3, Dark Falz/Olga Flow/Shambertin +4) plus difficulty bonuses (+1 Hard, +2 VHard, +3 Ult)!' => 'Гильдия Охотников объявила тотальную зачистку. Победите ЛЮБОГО босса в игре! Очки масштабируются по рангу босса (Dragon/Barba Ray +1, De Rol Le/Gol Dragon +2, Vol Opt/Gal Gryphon +3, Dark Falz/Olga Flow/Shambertin +4) плюс бонусы за сложность (+1 Hard, +2 VHard, +3 Ult)!',
        'Operation: Cataclysmic Core' => 'Операция: Ядро катаклизма',
        'The core dimensional anomalies threaten to destabilize Ragol! Cooperate to defeat the final boss of each episode: Dark Falz in Ep1 (+3 pts), Olga Flow in Ep2 (+4 pts), or Shambertin in Ep4 (+4 pts). Earn difficulty bonuses (+1 Hard, +2 VHard, +3 Ult)!' => 'Аномалии в ядре планеты угрожают дестабилизировать Рагол! Скооперируйтесь для победы над финальными боссами эпизодов: Dark Falz в Ep1 (+3 очка), Olga Flow в Ep2 (+4 очка) или Shambertin в Ep4 (+4 очка). Бонусы сложности (+1 Hard, +2 VHard, +3 Ult)!',
        'Currently Tracked Player Missions (Last 50)' => 'Текущие задания игроков (последние 50)',
